window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-318e36bf8c283018"]={"versions": [{"id": "FIG-318e36bf8c283018", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P04mForward</code> innerhalb des E2E-Profils 4m (End-to-End Communication Protection) gemäß <code>AUTOSAR_PRS_E2EProtocol</code>. Es beschreibt die algorithmische Abfolge bei der Weiterleitung und E2E-Schutzergänzung einer Nachricht im E2E-Forwarding-Kontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktion / Signatur</strong>: <code>E2E_P04mForward(Config, State, SourceID, MessageType, MessageResult, Data, Length, CheckStatus)</code></li>\n<li><strong>Eingangs- und Zustandsparameter</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur des E2E-Profils 4m</li>\n<li><code>State</code>: Zustandsstruktur (inklusive Alive-Counter)</li>\n<li><code>SourceID</code>: Quellidentifikator der Nachricht</li>\n<li><code>MessageType</code>: Typ der weiterzuleitenden Nachricht</li>\n<li><code>MessageResult</code>: Statusergebnis der vorhergehenden Prüfung / Verarbeitung</li>\n<li><code>Data</code>: Nutzdatenpuffer (Byte-Array)</li>\n<li><code>Length</code>: Datenlänge</li>\n<li><code>CheckStatus</code>: Status aus der vorangegangenen E2E-Prüfung (Typ referenziert über Hinweis auf <code>[PRS_E2E_00597]</code>)</li>\n<li><strong>Aktionen / Sub-Aktivitäten</strong>:</li>\n<li><code>Verify inputs of the forward function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Protect_Write Message Type</code></li>\n<li><code>Protect_Write SourceID</code></li>\n<li><code>Protect_Write Message Result</code></li>\n<li><code>Protect_Compute CRC</code></li>\n<li><code>Protect_Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li><strong>Rückgabewerte / Endzustände</strong>:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code></li>\n<li><code>return E2E_E_INPUTERR_WRONG</code></li>\n<li><code>return E2E_E_OK</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt am Initialknoten beim Aufruf von <code>E2E_P04mForward</code>.</li>\n<li>Verifikation der Funktionsparameter in <code>Verify inputs of the forward function</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls ein Zeiger null ist (<code>[null input]</code>): Verzweigung zum linken Endknoten mit Rückgabewert <code>return E2E_E_INPUTERR_NULL</code>.</li>\n<li>Falls Parameterwerte ungültig oder außerhalb des Wertebereichs liegen (<code>[wrong input]</code>): Verzweigung zum rechten Endknoten mit Rückgabewert <code>return E2E_E_INPUTERR_WRONG</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei erfolgreicher Validierung sequenzieller Kontrollfluss:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Compute offset</code>: Berechnung des E2E-Header-Offsets im Datenpuffer.</li>\n<li><code>Write Length</code>: Schreiben der Längenangabe.</li>\n<li><code>Write Counter</code>: Schreiben des aktuellen Counter-Werts.</li>\n<li><code>Write DataID</code>: Schreiben der Data-ID.</li>\n<li><code>Protect_Write Message Type</code>: Schreiben des Nachrichtentyps.</li>\n<li><code>Protect_Write SourceID</code>: Schreiben des Source-Identifiers.</li>\n<li><code>Protect_Write Message Result</code>: Schreiben des Message-Results.</li>\n<li><code>Protect_Compute CRC</code>: Berechnung der CRC über die definierten Header- und Nutzdatenbereiche.</li>\n<li><code>Protect_Write CRC</code>: Eintragen der berechneten CRC in das E2E-Headerfeld.</li>\n<li><code>Increment Counter</code>: Inkrementieren des Zählers für den nächsten Sende-/Weiterleitungszyklus im Zustandsobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Regulärer Abschluss am mittleren Endknoten mit Rückgabewert <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert das normative Verhalten für die Serialisierung und Absicherung von Metadaten und Nutzdaten bei E2E-Forwarding in Profil 4m. Implementierende Module müssen:</p>\n<ul class=\"fig-list\">\n<li>Die Eingangsvalidierung zwingend vor jeglicher Puffer- oder Zustandsmodifikation durchführen und bei Fehlern deterministisch <code>E2E_E_INPUTERR_NULL</code> bzw. <code>E2E_E_INPUTERR_WRONG</code> liefern.</li>\n<li>Die Felder (<code>Length</code>, <code>Counter</code>, <code>DataID</code>, <code>MessageType</code>, <code>SourceID</code>, <code>MessageResult</code> und <code>CRC</code>) in der vorgegebenen Reihenfolge und an den berechneten Offsets in den Datenstrom schreiben.</li>\n<li>Die CRC-Berechnung erst nach vollständigem Beschreiben aller geschützten Headerfelder ausführen.</li>\n<li>Den Alive-Counter im internen Zustandsdatenobjekt erst nach erfolgreicher Absicherung vor Rückgabe von <code>E2E_E_OK</code> inkrementieren.</li>\n<li>Den Typ von <code>CheckStatus</code> konform zur Anforderung <code>[PRS_E2E_00597]</code> auflösen.</li>\n</ul>"}, {"id": "FIG-f8bf0274f0692a93", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P04mForward</code> innerhalb des E2E-Profils 4m (End-to-End Communication Protection) gemäß <code>AUTOSAR_PRS_E2EProtocol</code>. Es beschreibt die algorithmische Abfolge bei der Weiterleitung und E2E-Schutzergänzung einer Nachricht im E2E-Forwarding-Kontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktion / Signatur</strong>: <code>E2E_P04mForward(Config, State, SourceID, MessageType, MessageResult, Data, Length, CheckStatus)</code></li>\n<li><strong>Eingangs- und Zustandsparameter</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur des E2E-Profils 4m</li>\n<li><code>State</code>: Zustandsstruktur (inklusive Alive-Counter)</li>\n<li><code>SourceID</code>: Quellidentifikator der Nachricht</li>\n<li><code>MessageType</code>: Typ der weiterzuleitenden Nachricht</li>\n<li><code>MessageResult</code>: Statusergebnis der vorhergehenden Prüfung / Verarbeitung</li>\n<li><code>Data</code>: Nutzdatenpuffer (Byte-Array)</li>\n<li><code>Length</code>: Datenlänge</li>\n<li><code>CheckStatus</code>: Status aus der vorangegangenen E2E-Prüfung (Typ referenziert über Hinweis auf <code>[PRS_E2E_00597]</code>)</li>\n<li><strong>Aktionen / Sub-Aktivitäten</strong>:</li>\n<li><code>Verify inputs of the forward function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Protect_Write Message Type</code></li>\n<li><code>Protect_Write SourceID</code></li>\n<li><code>Protect_Write Message Result</code></li>\n<li><code>Protect_Compute CRC</code></li>\n<li><code>Protect_Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li><strong>Rückgabewerte / Endzustände</strong>:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code></li>\n<li><code>return E2E_E_INPUTERR_WRONG</code></li>\n<li><code>return E2E_E_OK</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt am Initialknoten beim Aufruf von <code>E2E_P04mForward</code>.</li>\n<li>Verifikation der Funktionsparameter in <code>Verify inputs of the forward function</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls ein Zeiger null ist (<code>[null input]</code>): Verzweigung zum linken Endknoten mit Rückgabewert <code>return E2E_E_INPUTERR_NULL</code>.</li>\n<li>Falls Parameterwerte ungültig oder außerhalb des Wertebereichs liegen (<code>[wrong input]</code>): Verzweigung zum rechten Endknoten mit Rückgabewert <code>return E2E_E_INPUTERR_WRONG</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei erfolgreicher Validierung sequenzieller Kontrollfluss:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Compute offset</code>: Berechnung des E2E-Header-Offsets im Datenpuffer.</li>\n<li><code>Write Length</code>: Schreiben der Längenangabe.</li>\n<li><code>Write Counter</code>: Schreiben des aktuellen Counter-Werts.</li>\n<li><code>Write DataID</code>: Schreiben der Data-ID.</li>\n<li><code>Protect_Write Message Type</code>: Schreiben des Nachrichtentyps.</li>\n<li><code>Protect_Write SourceID</code>: Schreiben des Source-Identifiers.</li>\n<li><code>Protect_Write Message Result</code>: Schreiben des Message-Results.</li>\n<li><code>Protect_Compute CRC</code>: Berechnung der CRC über die definierten Header- und Nutzdatenbereiche.</li>\n<li><code>Protect_Write CRC</code>: Eintragen der berechneten CRC in das E2E-Headerfeld.</li>\n<li><code>Increment Counter</code>: Inkrementieren des Zählers für den nächsten Sende-/Weiterleitungszyklus im Zustandsobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Regulärer Abschluss am mittleren Endknoten mit Rückgabewert <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert das normative Verhalten für die Serialisierung und Absicherung von Metadaten und Nutzdaten bei E2E-Forwarding in Profil 4m. Implementierende Module müssen:</p>\n<ul class=\"fig-list\">\n<li>Die Eingangsvalidierung zwingend vor jeglicher Puffer- oder Zustandsmodifikation durchführen und bei Fehlern deterministisch <code>E2E_E_INPUTERR_NULL</code> bzw. <code>E2E_E_INPUTERR_WRONG</code> liefern.</li>\n<li>Die Felder (<code>Length</code>, <code>Counter</code>, <code>DataID</code>, <code>MessageType</code>, <code>SourceID</code>, <code>MessageResult</code> und <code>CRC</code>) in der vorgegebenen Reihenfolge und an den berechneten Offsets in den Datenstrom schreiben.</li>\n<li>Die CRC-Berechnung erst nach vollständigem Beschreiben aller geschützten Headerfelder ausführen.</li>\n<li>Den Alive-Counter im internen Zustandsdatenobjekt erst nach erfolgreicher Absicherung vor Rückgabe von <code>E2E_E_OK</code> inkrementieren.</li>\n<li>Den Typ von <code>CheckStatus</code> konform zur Anforderung <code>[PRS_E2E_00597]</code> auflösen.</li>\n</ul>"}], "trans": [{"from": "FIG-318e36bf8c283018", "to": "FIG-f8bf0274f0692a93", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
